mapper.select:
select uc.id as id, c.title as title, c.type as type, c.condition_amount as condition_amount,
       c.discount_amount as discount_amount, c.discount_rate as discount_rate,
       uc.status as status, c.valid_to as valid_to
FROM user_coupon uc LEFT JOIN coupon c ON uc.coupon_id = c.id


     AND uc.status = #{status}


     AND uc.user_id = #{userId}

select uc.id as userCouponId, c.id as couponId, c.title as title,
       c.type as type, c.condition_amount, c.discount_amount,
       c.discount_rate, c.valid_to as validTo
from coupon c inner join user_coupon uc on c.id = uc.coupon_id

    uc.status = 0

        AND c.condition_amount <= #{totalAmount}


        AND uc.user_id = #{userId}


        AND c.valid_from <= #{now} AND c.valid_to >= #{now}
